import * as THREE from 'three/webgpu';
import { color, mix, uv, dot, sin, fract, vec2, vec3 } from 'three/tsl';
import gsap from 'gsap';
import { createTextMesh } from '@/text';

const PX_TO_UNIT = 0.005; // hero: 124px -> 0.62 scene-unit em height

const DEFAULT_COLORS = {
  background: '#0b0b10',
  surface: '#14141a',
  ink: '#16161d',
  paper: '#e8ecf2',
  accent: '#ff2a38',
};

const DEFAULT_TYPOGRAPHY = {
  hero: { family: 'Lora', fontSize: 124, fontWeight: 600, letterSpacing: -0.015, lineHeight: 0.98 },
  kicker: { family: 'JetBrains Mono', fontSize: 18, fontWeight: 700, letterSpacing: 0.12, lineHeight: 1.4 },
  body: { family: 'JetBrains Mono', fontSize: 26, fontWeight: 400, letterSpacing: 0, lineHeight: 1.55 },
  caption: { family: 'JetBrains Mono', fontSize: 18, fontWeight: 400, letterSpacing: 0.08, lineHeight: 1.4 },
};

const DEFAULT_TEXT = {
  kicker: 'NOVA ATELIER / JOURNAL',
  heroLine1: 'PRECISION IS',
  heroLine2: 'A HABIT.',
  body: 'Notes from the bench: tolerances, tempering, and the case for slower watchmaking.',
  caption: 'ISSUE 12 / JULY 2026',
};

function collectMaterials(object3D) {
  const materials = [];
  object3D.traverse((child) => {
    if (child.material) materials.push(child.material);
  });
  return materials;
}

function riseIn(object3D, { delay = 0, distance = 0.4 } = {}) {
  const materials = collectMaterials(object3D);
  materials.forEach((m) => {
    m.transparent = true;
    m.opacity = 0;
  });
  const targetY = object3D.position.y;
  object3D.position.y = targetY + distance;
  const tl = gsap.timeline({ delay });
  tl.to(object3D.position, { y: targetY, duration: 0.7, ease: 'power3.out' }, 0);
  if (materials.length) {
    tl.to(materials, { opacity: 1, duration: 0.5, ease: 'power2.out' }, 0);
  }
  return tl;
}

function drawRule(object3D, { delay = 0 } = {}) {
  object3D.scale.x = 0.0001;
  const tl = gsap.timeline({ delay });
  tl.to(object3D.scale, { x: 1, duration: 0.5, ease: 'power2.out' });
  return tl;
}

export default function createNode(config, ctx) {
  const root = new THREE.Group();
  root.name = 'editorial-oversized-headline';

  // --- scene placement --------------------------------------------------
  const sp = config.scenePosition || {};
  root.position.set(sp.x ?? 0, sp.y ?? 0, sp.z ?? 0);
  const rot = sp.rotationXYZ || {};
  root.rotation.set(rot.x ?? 0, rot.y ?? 0, rot.z ?? 0);
  const scl = sp.scaleXYZ || {};
  root.scale.set(scl.x ?? 1, scl.y ?? 1, scl.z ?? 1);

  // --- data ---------------------------------------------------------------
  const colors = { ...DEFAULT_COLORS, ...(config.colors || {}) };
  const typography = {
    hero: { ...DEFAULT_TYPOGRAPHY.hero, ...(config.typography?.hero || {}) },
    kicker: { ...DEFAULT_TYPOGRAPHY.kicker, ...(config.typography?.kicker || {}) },
    body: { ...DEFAULT_TYPOGRAPHY.body, ...(config.typography?.body || {}) },
    caption: { ...DEFAULT_TYPOGRAPHY.caption, ...(config.typography?.caption || {}) },
  };

  const textItems = Array.isArray(config.textContent) ? config.textContent : [];
  const heroItems = textItems.filter((t) => t.role === 'hero');
  const kickerItem = textItems.find((t) => t.role === 'kicker');
  const bodyItem = textItems.find((t) => t.role === 'body');
  const captionItem = textItems.find((t) => t.role === 'caption');

  const kickerText = (kickerItem?.text ?? DEFAULT_TEXT.kicker).toUpperCase();
  const heroLine1 = heroItems[0]?.text ?? DEFAULT_TEXT.heroLine1;
  const heroLine2 = heroItems[1]?.text ?? DEFAULT_TEXT.heroLine2;
  const bodyText = bodyItem?.text ?? DEFAULT_TEXT.body;
  const captionText = captionItem?.text ?? DEFAULT_TEXT.caption;

  // --- full-bleed editorial plate (engineered gradient + grain) -----------
  const plateWidth = 7;
  const plateHeight = 5.5;
  const plateGeometry = new THREE.PlaneGeometry(plateWidth, plateHeight);
  const plateMaterial = new THREE.MeshBasicNodeMaterial();

  const uvNode = uv();
  const gradientNode = mix(color(colors.background), color(colors.surface), uvNode.y);
  const noiseSeed = dot(uvNode, vec2(12.9898, 78.233));
  const grainNode = fract(sin(noiseSeed).mul(43758.5453123)).sub(0.5).mul(0.015);
  plateMaterial.colorNode = gradientNode.add(vec3(grainNode, grainNode, grainNode));

  const plate = new THREE.Mesh(plateGeometry, plateMaterial);
  plate.position.set(0, -0.25, 0);
  root.add(plate);

  // --- kicker ---------------------------------------------------------------
  const kickerMesh = createTextMesh(ctx.fontAtlas, {
    text: kickerText,
    font: typography.kicker.family,
    weight: typography.kicker.fontWeight,
    size: typography.kicker.fontSize * PX_TO_UNIT,
    letterSpacing: typography.kicker.letterSpacing,
    lineHeight: typography.kicker.lineHeight,
    color: colors.paper,
    align: 'left',
    anchor: 'top-left',
  });
  kickerMesh.position.set(-3.1, 1.7, 0.02);
  root.add(kickerMesh);

  // --- hero (two lines, letterpress double-plate shadow trick) -------------
  function buildHeroLine(text, y) {
    const group = new THREE.Group();
    const shadow = createTextMesh(ctx.fontAtlas, {
      text,
      font: typography.hero.family,
      weight: typography.hero.fontWeight,
      size: typography.hero.fontSize * PX_TO_UNIT,
      letterSpacing: typography.hero.letterSpacing,
      lineHeight: typography.hero.lineHeight,
      color: colors.ink,
      align: 'left',
      anchor: 'top-left',
    });
    shadow.position.set(0, 0, -0.02);
    const front = createTextMesh(ctx.fontAtlas, {
      text,
      font: typography.hero.family,
      weight: typography.hero.fontWeight,
      size: typography.hero.fontSize * PX_TO_UNIT,
      letterSpacing: typography.hero.letterSpacing,
      lineHeight: typography.hero.lineHeight,
      color: colors.paper,
      align: 'left',
      anchor: 'top-left',
    });
    front.position.set(0, 0, 0);
    group.add(shadow, front);
    group.position.set(-3.1, y, 0.04);
    return group;
  }

  const heroGroup1 = buildHeroLine(heroLine1, 0.9);
  const heroGroup2 = buildHeroLine(heroLine2, 0.25);
  root.add(heroGroup1, heroGroup2);

  // --- accent underline rule -------------------------------------------------
  const ruleWidth = 2.2;
  const ruleHeight = 0.05;
  const ruleGeometry = new THREE.PlaneGeometry(ruleWidth, ruleHeight);
  const ruleMaterial = new THREE.MeshBasicNodeMaterial();
  ruleMaterial.colorNode = color(colors.accent).mul(1.2);
  const ruleMesh = new THREE.Mesh(ruleGeometry, ruleMaterial);
  ruleMesh.position.set(ruleWidth / 2, 0, 0);
  const ruleGroup = new THREE.Group();
  ruleGroup.add(ruleMesh);
  ruleGroup.position.set(-3.1, -0.15, 0.01);
  root.add(ruleGroup);

  // --- body paragraph ----------------------------------------------------
  const bodyMesh = createTextMesh(ctx.fontAtlas, {
    text: bodyText,
    font: typography.body.family,
    weight: typography.body.fontWeight,
    size: typography.body.fontSize * PX_TO_UNIT,
    letterSpacing: typography.body.letterSpacing,
    lineHeight: typography.body.lineHeight,
    color: colors.paper,
    align: 'left',
    anchor: 'top-left',
    maxWidth: 4.5,
  });
  bodyMesh.position.set(-3.1, -0.8, 0.02);
  root.add(bodyMesh);

  // --- caption -------------------------------------------------------------
  const captionMesh = createTextMesh(ctx.fontAtlas, {
    text: captionText,
    font: typography.caption.family,
    weight: typography.caption.fontWeight,
    size: typography.caption.fontSize * PX_TO_UNIT,
    letterSpacing: typography.caption.letterSpacing,
    lineHeight: typography.caption.lineHeight,
    color: colors.paper,
    align: 'left',
    anchor: 'top-left',
  });
  captionMesh.position.set(-3.1, -1.9, 0.02);
  root.add(captionMesh);

  // --- cinematic primitives (contract: apply every one declared) -----------
  (config.cinematicPrimitives || []).forEach((primitive) => {
    const fn = ctx.primitives && ctx.primitives[primitive.name];
    if (typeof fn === 'function') {
      fn(root, primitive.params);
    }
  });

  // --- entrance choreography: rise-in top-to-bottom, 80ms stagger ----------
  const timelines = [];
  timelines.push(riseIn(kickerMesh, { delay: 0 }));
  timelines.push(riseIn(heroGroup1, { delay: 0.08 }));
  timelines.push(riseIn(heroGroup2, { delay: 0.16 }));
  timelines.push(riseIn(bodyMesh, { delay: 0.24 }));
  timelines.push(riseIn(captionMesh, { delay: 0.32 }));
  // rule draws after hero has landed (hero lands ~0.16 + 0.7 = 0.86s)
  timelines.push(drawRule(ruleGroup, { delay: 0.9 }));

  // --- events (none declared for this element) ------------------------------
  root.userData.handlers = {};

  // --- cleanup ---------------------------------------------------------------
  root.userData.cleanup = () => {
    timelines.forEach((tl) => tl.kill());
    timelines.length = 0;
    root.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach((m) => m.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
    root.clear();
  };

  return root;
}
